import math
teststring = '4\n0 3 4 6\n3 0 2 1\n4 2 0 5\n6 1 5 0\n\n'
online = __file__ != '/home/jhli/py/Grakn/Problem_G2.py'
(true, false) = (True, False)
if True:

	def spitout():
		for c in teststring.splitlines():
			yield c
	_ito = spitout()
	if not online:

		def input():
			return next(_ito)

	def build_enum(*a):
		built = dict()
		for (i, c) in enumerate(a):
			built[c] = i
		return lambda x: built[x]
n = int(input())
E = [(0, 0)] * int(n * (n - 1) / 2)
P = 998244353
for i in range(n):
	L = list(map(int, input().split(' ')))
	for j in range(i + 1, n):
		E[L[j] - 1] = (i, j)
R = list(range(n))
C = [[0, 1] for _ in range(n)]
Nv = [1] * n
Ne = [0] * n

def root(x):
	if x == R[x]:
		return x
	else:
		R[x] = y = root(R[x])
		return y

def prod(A, B, da, db):
	C = [0] * (min(da + db, n) + 1)
	for i in range(da + 1):
		for j in range(db + 1):
			if i + j <= n:
				C[i + j] += A[i] * B[j]
				C[i + j] %= P
	return C
for (x, y) in E:
	r = rx = root(x)
	ry = root(y)
	if rx != ry:
		if r > ry:
			r = ry
		R[rx] = R[ry] = r
		C[r] = prod(C[rx], C[ry], Nv[rx], Nv[ry])
		Nv[r] = Nv[rx] + Nv[ry]
		Ne[r] = Ne[rx] + Ne[ry] + 1
	else:
		Ne[r] += 1
	if Ne[r] * 2 == Nv[r] * (Nv[r] - 1):
		C[r][1] = 1
print(' '.join(map(str, C[0][1:n + 1])))
